#ifndef COYOTE_UI_MUSE_AVATAR_H
#define COYOTE_UI_MUSE_AVATAR_H

#include <stdbool.h>

/*
 * The locally imported Muse avatar (avatars/muse_pixel.c).
 *
 * That file is generated by Muse for this device and is deliberately not in
 * git.  It is compiled in only when it is present, so a clean checkout builds
 * the plain UI and muse_avatar_available() reports false everywhere.
 */

#define MUSE_AVATAR_SIZE 64

/* The moods the renderer draws, as its mode numbers. */
typedef enum {
    MUSE_AVATAR_BOOT = 0,
    MUSE_AVATAR_IDLE = 1,
    MUSE_AVATAR_LISTENING = 2,
    MUSE_AVATAR_THINKING = 3,
    MUSE_AVATAR_SPEAKING = 4,
    MUSE_AVATAR_ERROR = 5,
    MUSE_AVATAR_OFF = 6,
} muse_avatar_mode_t;

/* True when an imported renderer was compiled into this firmware. */
bool muse_avatar_available(void);

/*
 * Draw the avatar MUSE_AVATAR_SIZE square at (x, y) in the given mood.  Each
 * call advances the pose by one frame, so call it at the avatar's frame rate
 * and never from a callback that must stay quick.
 */
void muse_avatar_draw(int x, int y, muse_avatar_mode_t mode);

#endif
